INSERT INTO Methodologie (titre, descriptif, img_presentation) VALUES
('Médecin', 'Professionnel de santé diplômé en médecine générale ou spécialisé, habilité à diagnostiquer et traiter les maladies.', NULL),
('Pharmacien', 'Expert du médicament, il délivre les ordonnances, conseille sur les traitements et veille à la sécurité thérapeutique.', NULL),
('Chirurgien-Dentiste', 'Spécialiste de la santé bucco-dentaire, il assure la prévention, le diagnostic et le traitement des pathologies dentaires.', NULL),
('Sage-Femme', 'Professionnelle de santé spécialisée dans le suivi de la grossesse, l\'accouchement et la santé des femmes.', NULL),
('Infirmier', 'Professionnel de soins qui assure la prévention, l\'évaluation et le traitement des réponses humaines aux problèmes de santé.', NULL),
('Masseur-Kinésithérapeute', 'Spécialiste de la rééducation fonctionnelle par le mouvement, le massage et les techniques manuelles et physiques.', NULL),
('Pédicure-Podologue', 'Professionnel de santé spécialisé dans le diagnostic et le traitement des affections du pied.', NULL),
('Technicien de Laboratoire', 'Expert en analyses biologiques, il réalise les examens de biologie médicale contribuant au diagnostic et au suivi des patients.', NULL),
('Orthophoniste', 'Spécialiste de la rééducation des troubles de la voix, de la parole, du langage oral et écrit.', NULL),
('Psychologue', 'Professionnel de la santé mentale qui évalue et accompagne les personnes dans leurs difficultés psychologiques et émotionnelles.', NULL),
('Ergothérapeute', 'Spécialiste qui aide les personnes à retrouver leur autonomie dans les activités de la vie quotidienne après un handicap ou une maladie.', NULL),
('Diététicien', 'Expert en nutrition qui conseille et accompagne les patients dans l\'adoption d\'une alimentation adaptée à leur état de santé.', NULL),
('Psychomotricien', 'Professionnel qui évalue et traite les troubles du mouvement et du comportement liés au développement psychomoteur.', NULL);
